  "code": "import re\n\n\ndef rule_esf_total_assets(doc: dict) -> list[dict]:\n    try:\n        pages = doc.get(\"pages\") or []\n        lines = doc.get(\"lines\") or []\n\n        def norm(text: str) -> str:\n            return \" \".join(re.sub(r\"[^a-z0-9]+\", \" \", (text or \"\").lower()).split())\n\n        def has_esf1(text: str) -> bool:\n            return bool(re.search(r\"\\btable\\s+esf\\s+[1l]\\b\", text))\n\n        def page_score(text: str) -> int:\n            score = 0\n            if \"exchange stabilization fund\" in text:\n                score += 3\n            if has_esf1(text):\n                score += 5\n            if \"balances as of\" in text or \"balance as of\" in text:\n                score += 3\n            if \"assets liabilities and capital\" in text:\n                score += 2\n            if \"total assets\" in text:\n                score += 6\n            if \"total liabilities and capital\" in text:\n                score += 4\n            if \"table of contents\" in text:\n                score -= 6\n            return score\n\n        if pages:\n            scored_pages = []\n            for page in pages:\n                raw_text = page.get(\"text\", \"\")\n                text = norm(raw_text)\n                score = page_score(text)\n                if score >= 10:\n                    scored_pages.append((score, page.get(\"page_no\", -1), raw_text))\n\n            if scored_pages:\n                scored_pages.sort(key=lambda item: (item[0], item[1]))\n                _, page_no, raw_text = scored_pages[-1]\n                span = {\n                    \"text\": raw_text,\n                    \"page_no\": page_no,\n                }\n                return [span]\n\n        if not lines:\n            return []\n\n        normalized_lines = [norm(line.get(\"text\", \"\")) for line in lines]\n\n        def join_window(start: int, end: int) -> str:\n            return \" \".join(normalized_lines[start:min(end, len(normalized_lines))])\n\n        start_candidates = []\n        for idx, text in enumerate(normalized_lines):\n            window = join_window(max(0, idx - 2), idx + 14)\n            if has_esf1(window) and (\n                \"balances as of\" in window\n                or \"balance as of\" in window\n                or \"exchange stabilization fund\" in window\n                or \"assets liabilities and capital\" in window\n            ):\n                start_candidates.append(idx)\n\n        if not start_candidates and \"exchange stabilization fund\" in norm(doc.get(\"text\", \"\")):\n            for idx in range(len(lines)):\n                window = join_window(max(0, idx - 8), idx + 40)\n                if (\n                    \"exchange stabilization fund\" in window\n                    and \"total assets\" in window\n                    and \"total liabilities and capital\" in window\n                ):\n                    start_candidates.append(max(0, idx - 8))\n\n        for start_idx in start_candidates:\n            total_idx = -1\n            for idx in range(start_idx, min(len(lines), start_idx + 260)):\n                if \"total assets\" in join_window(idx, idx + 4):\n                    total_idx = idx\n                    break\n\n            if total_idx == -1:\n                continue\n\n            end_idx = min(len(lines), total_idx + 90)\n            for idx in range(total_idx, min(len(lines), total_idx + 120)):\n                if \"total liabilities and capital\" in join_window(idx, idx + 4):\n                    end_idx = min(len(lines), idx + 60)\n                    break\n\n            begin_idx = max(start_idx, total_idx - 20)\n            snippet_lines = lines[begin_idx:end_idx]\n            snippet_text = \"\\n\".join(\n                (line.get(\"text\") or \"\").rstrip() for line in snippet_lines if line.get(\"text\")\n            )\n            if snippet_text.strip():\n                first_line = snippet_lines[0]\n                last_line = snippet_lines[-1]\n                span = {\n                    \"text\": snippet_text,\n                }\n                if \"page_no\" in first_line:\n                    span[\"page_no\"] = first_line.get(\"page_no\")\n                if \"line_no\" in first_line:\n                    span[\"line_no\"] = first_line.get(\"line_no\")\n                if \"page_no\" in last_line:\n                    span[\"end_page_no\"] = last_line.get(\"page_no\")\n                if \"line_no\" in last_line:\n                    span[\"end_line_no\"] = last_line.get(\"line_no\")\n                return [span]\n\n        return []\n    except Exception:\n        return []\n",
